menus.push(['creative','✧','海报广告定制']);
let creative={brand:'追悟时空',title:'让空间更智能',subtitle:'智能视觉 · 三维感知 · 行业应用',cta:'探索行业智能新可能',kind:'企业宣传海报',color:'#00cfff',ratio:'portrait',asset:'',assetName:''};
const cx=s=>escapeHTML(String(s)).replaceAll("'",'&#39;');
function creativeSVG(){let d=creative,w=1080,h=d.ratio==='portrait'?1440:d.ratio==='landscape'?608:1080;let title=Array.from(d.title),lines=[];for(let i=0;i<title.length;i+=12)lines.push(title.slice(i,i+12).join(''));return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#06172e"/><stop offset="1" stop-color="${d.color}" stop-opacity=".55"/></linearGradient></defs><rect width="100%" height="100%" fill="#06172e"/><rect width="100%" height="100%" fill="url(#g)"/><circle cx="960" cy="160" r="300" fill="none" stroke="${d.color}" stroke-width="2" opacity=".45"/><circle cx="960" cy="160" r="240" fill="none" stroke="${d.color}" opacity=".4"/>${d.asset?`<image href="${d.asset}" x="540" y="${h*.32}" width="480" height="${h*.5}" preserveAspectRatio="xMidYMid meet"/>`:''}<g font-family="Microsoft YaHei,Arial,sans-serif" fill="white"><text x="70" y="90" font-size="28" letter-spacing="6">${cx(d.brand)}</text><rect x="70" y="${h*.24}" width="70" height="7" fill="${d.color}"/>${lines.map((t,i)=>`<text x="70" y="${h*.24+85+i*76}" font-size="64" font-weight="bold">${cx(t)}</text>`).join('')}<text x="70" y="${h*.24+120+lines.length*76}" font-size="25">${cx(d.subtitle)}</text><text x="70" y="${h-110}" font-size="26" fill="${d.color}">${cx(d.cta)} →</text><text x="70" y="${h-45}" font-size="16" opacity=".55">追悟创意工作台 · 本地模板排版</text></g></svg>`}
function creativePrompt(){let d=creative;return `设计一张${d.kind}。品牌：${d.brand}。主标题必须准确呈现“${d.title}”；副标题：“${d.subtitle}”；行动文案：“${d.cta}”。画幅：${d.ratio==='portrait'?'3:4':d.ratio==='landscape'?'16:9':'1:1'}。采用深蓝背景，强调色${d.color}，清晰的中文排版，适当留白，层次分明。${d.asset?'保留用户上传产品或品牌素材的主体特征，不增加虚构标志。':'使用简洁的抽象几何视觉元素。'}不虚构产品参数、优惠或认证。`}
function creativeView(){return heading('海报与广告定制','品牌需求 → 素材 → 方案预览 → 下载',`<button data-nav="billing">${membership()} · 会员与充值</button>`)+`<div class="workspace"><section class="panel parameter"><span class="badge">创意方案工作台</span><h2>定制你的宣传方案</h2><label>应用类型<select id="crKind">${['企业宣传海报','产品推广广告','活动招募海报','电商产品广告'].map(x=>`<option ${creative.kind===x?'selected':''}>${x}</option>`).join('')}</select></label>${[['brand','品牌名称',24],['title','主标题',24],['subtitle','副标题',38],['cta','行动文案',24]].map(([k,l,n])=>`<label>${l}<input id="cr_${k}" maxlength="${n}" value="${cx(creative[k])}"></label>`).join('')}<label>尺寸<select id="crRatio"><option value="portrait">竖版 3:4</option><option value="square">方形 1:1</option><option value="landscape">横版 16:9</option></select></label><label>品牌强调色<input id="crColor" type="color" value="${creative.color}"></label><label>产品图 / Logo（PNG、JPG、WebP，最多 8 MB）<input id="crAsset" type="file" accept="image/png,image/jpeg,image/webp"></label><p id="crFile" class="subtle">${cx(creative.assetName||'素材仅在当前页面内使用')}</p><button id="crClear">移除素材</button><p class="note">当前使用本地模板排版，可免费下载；真实 AI 出图尚未接入，不消耗模拟 Token。</p></section><section class="panel result-panel"><div class="panel-head"><h2>实时方案预览</h2><span class="badge">模板排版 · 非 AI 出图</span></div><div id="crPreview" style="text-align:center;background:#031020;padding:20px"></div><div class="actions"><button id="crDownload" class="primary">下载海报 SVG</button><button id="crPrompt">下载生成需求</button></div><label>创意需求（可编辑后导出）<textarea id="crBrief" rows="6" style="width:100%"></textarea></label><p class="note">修改左侧内容会更新预览和需求文本。下载 SVG 可保留中文和素材；素材与方案刷新页面后清空。真实生成服务接入后，可沿用这份需求。</p><button data-nav="assistant">进入时空智能体</button></section></div>`}
function refreshCreative(){let svg=creativeSVG();$('#crPreview').innerHTML=`<img alt="定制海报实时预览" style="max-width:100%;max-height:570px" src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}">`;$('#crBrief').value=creativePrompt()}
const beforeCreativeRender=render;render=function(){beforeCreativeRender();if(activeView!=='creative')return;app.innerHTML=creativeView();$('#crRatio').value=creative.ratio;refreshCreative();for(let k of ['brand','title','subtitle','cta'])$('#cr_'+k).oninput=e=>{creative[k]=e.target.value;refreshCreative()};for(let [id,k] of [['crKind','kind'],['crRatio','ratio'],['crColor','color']])$('#'+id).oninput=e=>{creative[k]=e.target.value;refreshCreative()};$('#crAsset').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024){toast('请选择 8 MB 以内的 PNG、JPG 或 WebP 图片');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{creative.asset=reader.result;creative.assetName=f.name;if(activeView==='creative'){$('#crFile').textContent=f.name;refreshCreative()}};reader.readAsDataURL(f)};$('#crClear').onclick=()=>{creative.asset='';creative.assetName='';render()};$('#crDownload').onclick=()=>download(creativeSVG(),'追悟定制海报.svg','image/svg+xml;charset=utf-8');$('#crPrompt').onclick=()=>download($('#crBrief').value,'海报生成需求.txt','text/plain;charset=utf-8')};window.removeEventListener('hashchange',beforeCreativeRender);window.addEventListener('hashchange',render);render();
